  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Strength Coefficient$q$, $q$Strength Coefficient (MPa)$q$, $q$number$q$, $q$MPa$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Strain Rate Sensitivity$q$, $q$Strain Rate Sensitivity$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Hammer Strain Rate$q$, $q$Hammer Strain Rate (1/s)$q$, $q$number$q$, $q$1/s$q$, NULL, NULL, NULL, NULL, 3, true),
