    (v_id, $q$Flow Stress$q$, $q$Flow Stress (MPa)$q$, $q$calculated$q$, $q$MPa$q$, NULL, NULL, NULL, $q${Strength Coefficient} * {Hammer Strain Rate} ^ {Strain Rate Sensitivity}$q$, 7, false),
    (v_id, $q$Required Energy$q$, $q$Required Energy (J)$q$, $q$calculated$q$, $q$J$q$, NULL, NULL, NULL, $q${Energy Adjustment} * {Flow Stress} * {Forged Volume} * {Upset Strain} / 1000$q$, 8, false);
